// Plugin An Agent Plugins package installed into a harness: `plugin.json` at the root, MCP servers in
// `mcp.json`, skills under `skills/`. A client writes `files` (or passes back `blob`) and
// optionally `name` and `enabled`; the server derives `manifest`, `mcpServers`, `skills` and
// `skipped` from the package on every write and ignores those fields on input. A refused
// package leaves the harness unchanged.
type Plugin struct {
	// Blob Server-assigned handle for a package stored out of line. A client passes it back unchanged
	// and reads the files from the plugin files endpoint.
	Blob *string `json:"blob,omitempty"`

	// Enabled false keeps the plugin installed and inert; nothing in it is materialised or contacted.
	Enabled *bool `json:"enabled,omitempty"`

	// Files The package. Must contain `plugin.json` at its root.
	Files *[]SkillFile `json:"files,omitempty"`

	// Manifest `plugin.json`, parsed. Mirrors the Agent Plugins 1.0.0 manifest schema
	// (https://agent-plugins.org/schemas/1.0.0/plugin.schema.json, Apache-2.0) field for field, and
	// permits additional properties because a UHP client ignores fields it does not know. The
	// schema a manifest's own `$schema` names is authoritative; a server validates against that.
	Manifest *PluginManifest `json:"manifest,omitempty"`

	// McpServers Derived from `mcp.json`. Placeholders are reported unexpanded; `enabled` is always true,
	// the plugin's own `enabled` governs.
	McpServers *[]PluginMcpServer `json:"mcpServers,omitempty"`

	// Name The manifest's `name`. Optional on write; if sent it must equal the manifest's.
	Name string `json:"name"`

	// Skills Derived from `skills/`, one entry per immediate child directory with a SKILL.md.
	Skills *[]PluginSkill `json:"skills,omitempty"`

	// Skipped What the server found and could not load. Present on every plugin object the server
	// returns, empty when nothing was skipped.
	Skipped              *[]PluginSkipped       `json:"skipped,omitempty"`
	AdditionalProperties map[string]interface{} `json:"-"`
}

